// FUNCTION: BFME2 0x004EF464 size=56 name=?getMyEnemyPlayerIndex@AISkirmishPlayer@@IAEHXZ evidence=N:ledger tier=B hypothesis:cohesion
Int AISkirmishPlayer::getMyEnemyPlayerIndex()
{
	Int playerNdx;
	if (m_currentEnemy) {
		return m_currentEnemy->getPlayerIndex();
	}
	// For now, return first human player, as there should only be one. jba
	for (playerNdx = 0; playerNdx < ThePlayerList->getPlayerCount(); playerNdx++) {
		if (ThePlayerList->getNthPlayer(playerNdx)->m_playerType == PLAYER_HUMAN) {
			break;
		}
	}
	return playerNdx;
}


// FUNCTION: BFME2 0x004EF4C1 size=95 name=?rva004EF4C1@Rva004EF4C1@@QAEXXZ evidence=?:placeholder tier=B hypothesis:cohesion
void AISkirmishPlayer::doTeamBuilding()
{
	// See if any teams are expired.
	if (m_player->m_canBuildUnits) {
		// See if we are ready to start trying a team.
		if (!m_readyToBuildTeam) {
			m_teamTimer--;
			if (m_teamTimer <= 0) {
				m_readyToBuildTeam = true;
				m_teamDelay = 0;
			}
			if (m_teamTimer > 3 * BfmeLogicFramesPerSecond) {
				m_teamTimer = 3 * BfmeLogicFramesPerSecond;
			}
		}

		// This timer is to keep from banging on the logic each frame.
		m_teamDelay--;
		if (m_teamDelay < 1) {
			queueUnits(); // update the queues.
			if (m_readyToBuildTeam) {
				processTeamBuilding();
			}
			m_teamDelay = 2 * BfmeLogicFramesPerSecond;
		}
	}
}


// FUNCTION: BFME2 0x004EF52F size=143 name=?xfer@AISkirmishPlayer@@MAEXPAVXfer@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void AISkirmishPlayer::xfer(Xfer *xfer)
{
	// xfer base class info
	AIPlayer::xfer(xfer);

	if (xfer->IsLightCRC())
		return;

	// version
	xfer->Version1();

	*xfer == m_curFrontBaseDefense;
	*xfer == m_curFlankBaseDefense;
	*xfer == m_curFrontLeftDefenseAngle;
	*xfer == m_curFrontRightDefenseAngle;
	*xfer == m_curLeftFlankLeftDefenseAngle;
	*xfer == m_curLeftFlankRightDefenseAngle;
	*xfer == m_curRightFlankLeftDefenseAngle;
	*xfer == m_curRightFlankRightDefenseAngle;
}


